  add(rud.name,P(rud));add(anc.name,P(anc));if(mot.id)add(`Motor ${mot.name}`,P(mot));
  let slots=0,week=0;for(const [id,n] of Object.entries(s.rooms||{})){const r=get(sh.rooms,id),q=clamp(n,0,99);if(!r||!q)continue;slots+=r.slots*q;week+=r.week*q;add(`${r.name} ×${q}`,r.price*q);}
  let guns=0;for(const [id,n] of Object.entries(s.cannons||{})){const g=get(sh.cannons,id),q=clamp(n,0,99);if(!g||!q)continue;guns+=q;add(`${g.name} ×${q}`,P(g)*q);}
  const spec=[];for(const [id,n] of Object.entries(s.special||{})){const g=get(sh.special||[],id),q=clamp(n,0,999);if(!g||!q)continue;spec.push(`${g.name} ×${q}`);if(g.price)add(`${g.name} ×${q}`,g.price*q);}
  if(s.masts.length>size.max_masts)c.push(`${size.name}: no máximo ${size.max_masts} mastro${size.max_masts>1?'s':''}.`);
  const mm=String(size.mast_min).match(/(\d+)\s+(\S+)/);if(mm){const need=Number(mm[1]),kind=norm(mm[2]).replace(/s$/,'').replace('multiplo','multiplo');const r=rank[kind]||1;if(s.masts.filter(x=>(rank[x.type]||1)>=r).length<need)c.push(`${size.name}: mastro mínimo ${size.mast_min} (p. 279).`);}
